package br.com.wdc.store.view.teavm;

import br.com.wdc.store.presentation.presenter.open.login.LoginPresenter;
import br.com.wdc.store.view.teavm.app.StoreTeaVMApplication;
import br.com.wdc.store.view.teavm.commons.I18n;
import br.com.wdc.store.view.teavm.commons.interop.Console;
import br.com.wdc.store.view.teavm.infra.EncryptedLocalStorage;

/**
 * Entry point of the TeaVM application.
 * Called after the JavaScript generated by TeaVM is loaded.
 */
public class Main {

    public static void main(String[] args) {
        try {
            Console.log("WDC Store TeaVM - Initializing...");

            // The language of the texts, picked once from the browser's
            I18n.init();

            // API base URL - can be set through an attribute in the HTML
            String apiBaseUrl = getApiBaseUrl();
            Console.log("API Base URL: " + apiBaseUrl);

            // Detects the environment: native Tauri uses shellId "tn", the browser uses "tw".
            // The shellId is the localStorage namespace that isolates data between shells.
            String shellId = isTauri() ? "tn" : "tw";
            Console.log("Shell ID: " + shellId);

            // Sets the secure storage prefix BEFORE creating the application,
            // so set/remove always use the same "<shellId>:sec." prefix.
            EncryptedLocalStorage.configure(shellId);
            // Removes legacy entries written with the bare "sec." prefix (no shellId).
            cleanLegacyStoragePrefix("sec.");

            // Creates the application and initializes the secure storage (IndexedDB + AES-GCM)
            // before starting the app, so tryRestore() finds the encrypted tokens.
            StoreTeaVMApplication app = new StoreTeaVMApplication(apiBaseUrl, shellId);
            Console.log("WDC Store TeaVM - App created, initializing secure storage...");
            EncryptedLocalStorage.initialize(() -> {
                app.start();
                removeLoadingScreen();
                LoginPresenter.simulateSlowLogin(false);
                Console.log("WDC Store TeaVM - Started.");
            });
        } catch (Exception e) {
            Console.error("WDC Store TeaVM - FATAL: " + e.getClass().getName() + ": " + e.getMessage());
            showError(e.getClass().getName() + ": " + e.getMessage());
        }
    }

    @org.teavm.jso.JSBody(params = {"prefix"}, script = ""
            + "try {"
            + "  var keys = [];"
            + "  for (var i = 0; i < localStorage.length; i++) {"
            + "    var k = localStorage.key(i);"
            + "    if (k && k.startsWith(prefix)) keys.push(k);"
            + "  }"
            + "  keys.forEach(function(k) { localStorage.removeItem(k); });"
            + "} catch(e) {}")
    private static native void cleanLegacyStoragePrefix(String prefix);

    @org.teavm.jso.JSBody(params = {"msg"}, script = ""
            + "var el = document.getElementById('loading');"
            + "if (el) { el.style.color='red'; el.textContent = 'ERROR: ' + msg; }")
    private static native void showError(String msg);

    @org.teavm.jso.JSBody(params = {}, script = ""
            + "var el = document.getElementById('loading');"
            + "if (el) el.remove();")
    private static native void removeLoadingScreen();

    @org.teavm.jso.JSBody(params = {}, script = ""
            + "var meta = document.querySelector('meta[name=\"api-base-url\"]');"
            + "return (meta && meta.content) ? meta.content : '';")
    private static native String getApiBaseUrl();

    /** Returns true when running inside a Tauri native shell (desktop, Android, iOS). */
    @org.teavm.jso.JSBody(params = {}, script = ""
            + "return typeof window !== 'undefined' && typeof window.__TAURI_INTERNALS__ !== 'undefined';")
    private static native boolean isTauri();

}
